import json
import sys
from pathlib import Path
import numpy as np
from rcb_client import Robot

OUT = Path('/app/output')
r = Robot()
spec = r.spec()
LOW, HIGH = np.asarray(spec['action_types']['joint_position']['range_rad']).T

def action(q):
    return np.clip(2 * (np.asarray(q) - LOW) / (HIGH - LOW) - 1, -1, 1)

def record(res, name):
    res.save(OUT / name)
    print(json.dumps(res.meta), flush=True)
    return res

if __name__ == '__main__':
    command = sys.argv[1] if len(sys.argv) > 1 else 'inspect'
    if command == 'inspect':
        (OUT / 'spec.json').write_text(json.dumps(spec, indent=2))
        record(r.get_obs(), 'initial')
    elif command == 'status':
        print(r.status())
    elif command == 'observe':
        record(r.get_obs(), sys.argv[2] if len(sys.argv)>2 else 'current')
    elif command == 'pose':
        q = np.array(json.loads(sys.argv[2]))
        steps = int(sys.argv[3])
        record(r.submit('joint_position', np.tile(action(q), (steps,1)), cameras=None, video='frames'), sys.argv[4])
